pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), 0); }
    function testFuzz_property(uint256 amount) public {
        // Ensure amount is within a reasonable range to avoid overflow issues
        vm.assume(amount > 0 && amount < 1e30);

        // First open the contract to the public
        c.OpenToThePublic();

        // Record the state before calling AdjustBetAmounts
        bool beforeOpen = c.openToPublic();

        // Call AdjustBetAmounts
        c.AdjustBetAmounts(amount);

        // The general rule: after AdjustBetAmounts, openToPublic should remain unchanged
        // (the onlyOwner modifier should not affect openToPublic)
        assertTrue(c.openToPublic() == beforeOpen);
    }
}

