pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), 0); }
    function testFuzz_property(uint256 betLimit, uint256 msgValue) public {
        // Restrict inputs: betLimit must be > 0 to have a meaningful difference, msgValue > 0
        vm.assume(betLimit > 0);
        vm.assume(msgValue > 0);

        // Open to public
        c.OpenToThePublic();

        // Adjust bet limit
        c.AdjustBetAmounts(betLimit);

        // Deal ether to caller
        vm.deal(address(this), msgValue);

        // Try to call wager with msgValue > 0; should revert because wagers[msg.sender] == 0 initially
        // But the reference requires msg.value == betLimit, so with msgValue != betLimit it reverts.
        // We want to test the general rule: wager() reverts for any nonzero msg.value after AdjustBetAmounts.
        // This is trivially true if we call with msgValue != betLimit (reverts in reference).
        // To detect the bug, we need to call with msgValue != 0 and see if it reverts.
        // The buggy version only accepts msg.value == 0, so it will revert for any msgValue > 0 as well.
        // This test will pass for both (both revert), so this is not a suitable property.
        // Instead, we need a property that distinguishes: after AdjustBetAmounts, wager() should allow msg.value == betLimit and reject others.
        // But the bug only changes to msg.value == 0, so we need to show that buggy version allows msg.value == 0 (which it does) and reference rejects it.
        // So the property: after AdjustBetAmounts, calling wager() with msg.value == 0 reverts for reference but not for buggy.
        // Let's test that.

        // Actually, we need to ensure wagers[msg.sender] == 0 first, which is true initially.

        // Now call wager with msg.value == 0
        (bool success, ) = address(c).call{value: 0}(abi.encodeWithSignature("wager()"));
        // In the reference (P), this should revert because require(msg.value == betLimit) fails (betLimit > 0, msg.value == 0)
        // In the buggy version (M), this should succeed (since require(msg.value == 0) passes)
        // So we assert that wager() reverts for the reference (which is the correct behavior)
        // The general rule: after AdjustBetAmounts with any betLimit > 0, calling wager() with msg.value == 0 always reverts.
        assertTrue(!success, "wager() should revert when msg.value == 0 after AdjustBetAmounts");
    }
}

