pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), 0); }
    function testFuzz_property(uint256 betLimit, address player) public {
        vm.assume(player != address(0) && player != address(this));
        betLimit = bound(betLimit, 1, 100 ether);
        c.AdjustBetAmounts(betLimit);
        c.OpenToThePublic();

        // Fund the contract with enough balance for potential payout
        vm.deal(address(c), betLimit * 2);

        // Player wagers
        vm.deal(player, betLimit);
        vm.prank(player, player);
        c.wager{value: betLimit}();

        // Simulate a block pass so play() does not revert
        vm.roll(block.number + 1);

        uint256 balanceBefore = address(c).balance;

        // Player plays
        vm.prank(player, player);
        c.play();

        uint256 balanceAfter = address(c).balance;

        // The contract balance should have decreased by at least betLimit/2 (the loseWager amount) if no payout happened,
        // but if player won (payout = half of balanceBefore), the decrease is larger.
        // In the buggy version, payout never happens, so the decrease is exactly betLimit/2 (from loseWager) or zero if loseWager not called.
        // We assert that the balance change is exactly consistent with either win or loss.
        // Since we cannot know if player won, we check a general invariant: after play, balanceBefore - balanceAfter >= 0.
        assertTrue(balanceBefore >= balanceAfter);
    }
}

