pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), 0); }
    function testFuzz_property(uint256 newBetLimit, address player) public {
        vm.assume(newBetLimit > 0 && newBetLimit <= address(this).balance / 2 + 1);
        vm.assume(player != address(0) && player != address(this));
        // Make the contract open to public
        c.OpenToThePublic();
        // Give player enough ETH to wager
        vm.deal(player, newBetLimit);
        // Player wagers
        vm.prank(player, player);
        c.wager{value: newBetLimit}();
        // Advance block number so play can proceed
        vm.roll(block.number + 1);
        // Player plays
        vm.prank(player, player);
        c.play();
        // Now change betLimit
        c.AdjustBetAmounts(newBetLimit / 2); // arbitrary change
        // After the call, the invariant: totalDonated + contract balance == 2 * original betLimit
        uint256 totalDonated = c.totalDonated(); // public getter
        uint256 contractBalance = address(c).balance;
        uint256 expectedTotal = 2 * newBetLimit; // original betLimit * 2
        assertTrue(contractBalance + totalDonated == expectedTotal, "Rule: donated + balance should equal twice the win/lose amounts");
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), 0); }
    function testFuzz_property(uint256 newBetLimit) public {
        // Phase 1: open to public and set initial bet limit
        c.OpenToThePublic();
        uint256 initialBetLimit = 0; // zero means no wagers possible initially
        // Phase 2: set a random new bet limit via AdjustBetAmounts
        newBetLimit = bound(newBetLimit, 1, 1e18); // non-zero
        c.AdjustBetAmounts(newBetLimit);
        // Phase 3: simulate a wager and play (lose) to observe the balance change
        // First, send ETH to contract to cover the wager scenario
        vm.deal(address(this), 2 * newBetLimit);
        // Record state before wager
        uint256 balanceBefore = address(c).balance;
        uint256 totalDonatedBefore = c.totalDonated(); // public getter
        // Wager and play as a user (this contract is tx.origin)
        c.wager{value: newBetLimit}();
        c.play();
        // Record state after
        uint256 balanceAfter = address(c).balance;
        uint256 totalDonatedAfter = c.totalDonated();
        // Rule: The sum (balance + totalDonated) should remain constant
        // because the wager amount is sent to contract, then on lose it sends betLimit/2 to whale (donated) and keeps the rest
        // But note: the wager adds newBetLimit to balance, then loseWager subtracts (betLimit/2) from balance and adds to totalDonated
        // So balance change = newBetLimit - (newBetLimit/2) = newBetLimit/2
        // totalDonated change = newBetLimit/2
        // Hence sum_after - sum_before = (newBetLimit/2) + (newBetLimit/2) - newBetLimit = 0
        // Actually balance_before includes the sent wager? Let's check: we sent 2*newBetLimit, but wager consumes newBetLimit
        // Simpler: assert that the sum before == sum after
        assertTrue(balanceBefore + totalDonatedBefore == balanceAfter + totalDonatedAfter);
    }
}

